#if !SENTINEL_USB_ADMISSION_BASELINE_QUALIFICATION
#error Readonly baseline qualification only.
#endif
using System;using System.IO;using System.Diagnostics;using System.Security.Principal;using Microsoft.Win32;
internal static class UsbLegacyBaselineQualification {
 static void Receipt(string state,int stage){using(var key=Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Sentinel\UsbLegacyBaselineQualification")){key.SetValue("State",state,RegistryValueKind.String);key.SetValue("Stage",stage,RegistryValueKind.DWord);key.Flush();}}
 [STAThread]public static int Main(string[] args){if(args.Length!=0)return 2;if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 3;int stage=1;try{Receipt("running",stage);byte[] binding;using(var initial=UsbLegacyReleasedBaseline.Acquire(null)){initial.Check();binding=initial.Binding;}stage=2;string shell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");using(var sleeper=new Process()){sleeper.StartInfo=new ProcessStartInfo(shell,"-NoProfile -Command Start-Sleep -Seconds 5"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};sleeper.Start();try{stage=3;using(var expected=UsbLegacyReleasedBaseline.Acquire(binding)){expected.Check();stage=4;if(!UsbAdmissionWorkerBackend.QualificationFreshReleasedBaseline(expected))throw new InvalidOperationException("Released baseline verification failed");expected.Check();}stage=5;if(!sleeper.WaitForExit(10000)||sleeper.ExitCode!=0)throw new InvalidOperationException("Qualification sleeper failed");}finally{if(!sleeper.HasExited){sleeper.Kill();sleeper.WaitForExit(1000);}}}Receipt("complete",0);return 0;}catch(Exception error){Receipt("failed",stage);Console.WriteLine("FAIL readonly baseline stage "+stage+" category "+UsbAdmissionWorkerBackend.FailureCategory(error)+" reason "+UsbAdmissionWorkerBackend.FailureReason(error)+" hresult "+error.HResult.ToString("X8"));return 1;}}
}
